using System.Diagnostics;
using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;

if (args.Length != 2) throw new ArgumentException("Usage: fixture audit.dll output-directory");
string directory = Path.GetFullPath(args[1]);
Directory.CreateDirectory(directory);
using AssemblyDefinition assembly = AssemblyDefinition.CreateAssembly(
    new AssemblyNameDefinition("SlotMetadataFixture", new Version(1, 0)), "SlotMetadataFixture.dll", ModuleKind.Dll);
ModuleDefinition module = assembly.MainModule;
const string ns = "MegaCrit.Sts2.Core.Models";
TypeDefinition root = AddType(ns, "AbstractModel", module.TypeSystem.Object);
MethodDefinition rootDo = AddMethod(root, "Do", module.TypeSystem.Void, newSlot: true);
MethodDefinition rootGet = AddMethod(root, "GetValue", module.TypeSystem.Object, newSlot: true);
MethodDefinition rootOther = AddMethod(root, "Other", module.TypeSystem.Void, newSlot: true);
TypeDefinition middle = AddType(ns, "Middle", root);
MethodDefinition middleDo = AddMethod(middle, "Do", module.TypeSystem.Void, newSlot: false);
TypeDefinition leaf = AddType(ns, "Leaf", middle);
MethodDefinition leafDo = AddMethod(leaf, "Do", module.TypeSystem.Void, newSlot: false);
MethodDefinition leafOverload = AddMethod(leaf, "Do", module.TypeSystem.Void, newSlot: true);
leafOverload.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, module.TypeSystem.Int32));
TypeDefinition newLeaf = AddType(ns, "NewLeaf", middle);
MethodDefinition hiding = AddMethod(newLeaf, "Do", module.TypeSystem.Void, newSlot: true);

// The external parent has exactly the same FullName as the local root. The
// scanner must preserve its different assembly scope rather than bind locally.
var externalAssembly = new AssemblyNameReference("ForeignModels", new Version(1, 0));
module.AssemblyReferences.Add(externalAssembly);
var externalParent = new TypeReference(ns, "AbstractModel", module, externalAssembly);
TypeDefinition externalLeaf = AddType(ns, "ExternalLeaf", externalParent);
MethodDefinition externalDo = AddMethod(externalLeaf, "Do", module.TypeSystem.Void, newSlot: false);
TypeDefinition localValue = AddType(ns, "Value", module.TypeSystem.Object);
var externalValue = new TypeReference(ns, "Value", module, externalAssembly);
MethodDefinition rootWithValue = AddMethod(root, "WithValue", module.TypeSystem.Void, newSlot: true);
rootWithValue.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, localValue));
MethodDefinition externalParameter = AddMethod(leaf, "WithValue", module.TypeSystem.Void, newSlot: false);
externalParameter.Parameters.Add(new ParameterDefinition("value", ParameterAttributes.None, externalValue));

// Covariant-looking reuse is an explicit unknown for this metadata tool.
// The closest base must not be skipped to bind an older matching return type.
TypeDefinition covariant = AddType(ns, "Covariant", root);
MethodDefinition covariantGet = AddMethod(covariant, "GetValue", module.TypeSystem.String, newSlot: false);
TypeDefinition afterCovariant = AddType(ns, "AfterCovariant", covariant);
MethodDefinition afterCovariantGet = AddMethod(afterCovariant, "GetValue", module.TypeSystem.Object, newSlot: false);
TypeDefinition explicitLeaf = AddType(ns, "ExplicitLeaf", root);
MethodDefinition renamed = AddMethod(explicitLeaf, "Renamed", module.TypeSystem.Void, newSlot: true);
renamed.Overrides.Add(rootDo);
MethodDefinition multiple = AddMethod(explicitLeaf, "Multiple", module.TypeSystem.Void, newSlot: true);
multiple.Overrides.Add(rootDo);
multiple.Overrides.Add(rootOther);

// Supply one actual Hook call edge, so same-name hiding is checked against
// the referenced root slot rather than inferred from its name.
TypeDefinition hook = AddType("MegaCrit.Sts2.Core.Hooks", "Hook", module.TypeSystem.Object);
var dispatch = new MethodDefinition("Dispatch", MethodAttributes.Public | MethodAttributes.Static, module.TypeSystem.Void);
hook.Methods.Add(dispatch);
dispatch.Parameters.Add(new ParameterDefinition("model", ParameterAttributes.None, root));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Ldarg_0));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt, rootDo));
dispatch.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
string dll = Path.Combine(directory, "fixture.dll");
assembly.Write(dll);
string output = Path.Combine(directory, "audit.json");
var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true };
start.ArgumentList.Add(Path.GetFullPath(args[0])); start.ArgumentList.Add(dll); start.ArgumentList.Add(output);
using Process process = Process.Start(start) ?? throw new InvalidOperationException("Could not start audit tool");
Task<string> stdout = process.StandardOutput.ReadToEndAsync();
Task<string> stderr = process.StandardError.ReadToEndAsync();
await process.WaitForExitAsync();
if (process.ExitCode != 0) throw new InvalidOperationException(await stdout + await stderr);
using JsonDocument json = JsonDocument.Parse(File.ReadAllText(output));
Dictionary<string, JsonElement> slots = json.RootElement.GetProperty("virtualModelSlots")
    .EnumerateArray().ToDictionary(slot => slot.GetProperty("Method").GetString()!);
var checks = new List<object>();
Check("inherited-chain", leafDo, "resolved-local", rootDo.FullName, true, 3);
Check("overload-new-slot", leafOverload, "resolved-local", leafOverload.FullName, false, 1);
Check("same-name-hiding", hiding, "resolved-local", hiding.FullName, false, 1);
Check("external-homonym", externalDo, "external-or-unresolved-base", externalParent.FullName, false, 1);
Check("external-parameter-homonym", externalParameter, "external-or-unresolved-base", module.TypeSystem.Object.FullName, false, 1);
Check("covariant-return", covariantGet, "covariant-or-unresolved-return", rootGet.FullName, false, 1);
Check("closest-covariant-base", afterCovariantGet, "covariant-or-unresolved-return", covariantGet.FullName, false, 1);
Check("explicit-renamed-slot", renamed, "resolved-local", rootDo.FullName, true, 2);
Check("multiple-explicit-slots", multiple, "multiple-explicit-slots", null, false, 1);
string result = JsonSerializer.Serialize(new { passed = checks.Count, checks, nativeExecution = false,
    scannerOutput = await stdout, scannerError = await stderr }, new JsonSerializerOptions { WriteIndented = true });
File.WriteAllText(Path.Combine(directory, "result.json"), result + "\n");
Console.WriteLine($"SLOT_METADATA_BOUNDARIES_OK cases={checks.Count}");


using (AssemblyDefinition ambiguityAssembly = AssemblyDefinition.CreateAssembly(
    new AssemblyNameDefinition("AmbiguityMetadataFixture", new Version(1, 0)), "AmbiguityMetadataFixture.dll", ModuleKind.Dll))
{
    ModuleDefinition am = ambiguityAssembly.MainModule;
    TypeDefinition AT(string name, TypeReference parent)
    {
        var type = new TypeDefinition(ns, name, TypeAttributes.Public | TypeAttributes.Class, parent);
        am.Types.Add(type); return type;
    }
    MethodDefinition AM(TypeDefinition type, string name, bool isNewSlot = true)
    {
        var attrs = MethodAttributes.Public | MethodAttributes.Virtual | MethodAttributes.HideBySig;
        if (isNewSlot) attrs |= MethodAttributes.NewSlot;
        var method = new MethodDefinition(name, attrs, am.TypeSystem.Void);
        type.Methods.Add(method);method.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));return method;
    }
    var ar = AT("GenericArityRoot", am.TypeSystem.Object);
    var nonGeneric = AM(ar, "Same");
    var generic = AM(ar, "Same");
    generic.GenericParameters.Add(new GenericParameter("Unused", generic));
    if (nonGeneric.FullName != generic.FullName) throw new InvalidOperationException("No display-signature collision in fixture.");
    var alias = AM(AT("ExplicitAlias", ar), "Alias");alias.Overrides.Add(nonGeneric);
    var twinOne = AT("DuplicateType", am.TypeSystem.Object);
    var twinTwo = AT("DuplicateType", am.TypeSystem.Object);
    AM(twinOne, "Do");AM(twinTwo, "Do");
    AM(AT("DerivedFromDuplicateType", twinOne), "Do", false);
    var calls = AT("CallSites", am.TypeSystem.Object);
    foreach (var (name, target) in new[] { ("CallPlain", (MethodReference)nonGeneric),
        ("CallGeneric", (MethodReference)new GenericInstanceMethod(generic)) })
    {
        if (target is GenericInstanceMethod constructed) constructed.GenericArguments.Add(am.TypeSystem.String);
        var method = new MethodDefinition(name, MethodAttributes.Public | MethodAttributes.Static, am.TypeSystem.Void);
        calls.Methods.Add(method);
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Callvirt, target));
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Ret));
    }
    string ambiguityDll = Path.Combine(directory, "ambiguity-fixture.dll");ambiguityAssembly.Write(ambiguityDll);
    string ambiguityOutput = Path.Combine(directory, "ambiguity-audit.json");
    var astart = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true };
    astart.ArgumentList.Add(Path.GetFullPath(args[0]));astart.ArgumentList.Add(ambiguityDll);astart.ArgumentList.Add(ambiguityOutput);
    using Process ap = Process.Start(astart) ?? throw new InvalidOperationException("Could not start ambiguity scan.");
    Task<string> aout = ap.StandardOutput.ReadToEndAsync(), aerr = ap.StandardError.ReadToEndAsync();
    await ap.WaitForExitAsync();
    if (ap.ExitCode != 0) throw new InvalidOperationException(await aout + await aerr);
    using JsonDocument aj = JsonDocument.Parse(File.ReadAllText(ambiguityOutput));
    JsonElement[] aslots = aj.RootElement.GetProperty("virtualModelSlots").EnumerateArray().ToArray();
    var achecks = new List<string>();
    void ACheck(string name, bool passed)
    {
        if (!passed) throw new InvalidOperationException(name);achecks.Add(name);
    }
    JsonElement[] dupSlots = aslots.Where(row => row.GetProperty("Method").GetString() == nonGeneric.FullName).ToArray();
    ACheck("same-display-generic-arity-retained-and-conservative", dupSlots.Length == 2
        && dupSlots.All(row => row.GetProperty("Status").GetString() == "ambiguous-method-identity")
        && aj.RootElement.GetProperty("ambiguousMethodSignatures").EnumerateArray()
            .Single(row => row.GetProperty("signature").GetString() == nonGeneric.FullName)
            .GetProperty("methods").EnumerateArray().Select(row => row.GetProperty("genericParameterCount").GetInt32())
            .Order().SequenceEqual(new[] { 0, 1 }));
    ACheck("ambiguous-explicit-slot-refused", aslots.Single(row => row.GetProperty("Method").GetString() == alias.FullName)
        .GetProperty("Status").GetString() == "ambiguous-explicit-slot");
    ACheck("duplicate-declaring-types-retained-and-refused", aj.RootElement.GetProperty("ambiguousTypeSignatures").GetArrayLength() == 1
        && aslots.Count(row => row.GetProperty("Status").GetString() == "ambiguous-declaring-type") == 2);
    ACheck("duplicate-base-type-refused", aslots.Count(row => row.GetProperty("Status").GetString() == "ambiguous-base-type") == 1);
    JsonElement[] edges = aj.RootElement.GetProperty("staticReferences").EnumerateArray()
        .Where(row => row.GetProperty("Target").GetString() == nonGeneric.FullName).ToArray();
    ACheck("caller-and-operand-tokens-distinguish-call-sites", edges.Length == 2
        && edges.Select(row => row.GetProperty("CallerDefinitionToken").GetInt32()).Distinct().Count() == 2
        && edges.Select(row => row.GetProperty("OperandMetadataToken").GetInt32()).Distinct().Count() == 2
        && edges.Select(row => row.GetProperty("GenericArguments").GetArrayLength()).Order().SequenceEqual(new[] { 0, 1 }));
    File.WriteAllText(Path.Combine(directory, "ambiguity-result.json"), JsonSerializer.Serialize(new {
        passed = achecks.Count, checks = achecks, nativeExecution = false,
        scannerOutput = await aout, scannerError = await aerr }, new JsonSerializerOptions { WriteIndented = true }) + "\n");
    Console.WriteLine($"AMBIGUITY_METADATA_BOUNDARIES_OK cases={achecks.Count}");
}

TypeDefinition AddType(string typeNamespace, string name, TypeReference parent)
{
    var type = new TypeDefinition(typeNamespace, name, TypeAttributes.Public | TypeAttributes.Class, parent);
    module.Types.Add(type); return type;
}
MethodDefinition AddMethod(TypeDefinition type, string name, TypeReference resultType, bool newSlot)
{
    var attributes = MethodAttributes.Public | MethodAttributes.Virtual | MethodAttributes.HideBySig;
    if (newSlot) attributes |= MethodAttributes.NewSlot;
    var method = new MethodDefinition(name, attributes, resultType); type.Methods.Add(method);
    if (resultType.FullName != module.TypeSystem.Void.FullName)
        method.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));
    method.Body.Instructions.Add(Instruction.Create(OpCodes.Ret)); return method;
}
void Check(string name, MethodDefinition method, string status, string? rootSlot, bool hookTarget, int chainLength)
{
    JsonElement slot = slots[method.FullName];
    if (slot.GetProperty("Status").GetString() != status
        || slot.GetProperty("RootOrUnresolved").GetString() != rootSlot
        || slot.GetProperty("IsNativeHookTarget").GetBoolean() != hookTarget
        || slot.GetProperty("Chain").GetArrayLength() != chainLength)
        throw new InvalidOperationException($"{name}: {slot.GetRawText()}");
    checks.Add(new { name, method = method.FullName, status, rootSlot, hookTarget, chainLength });
}

