	}

	private static FreePlayResolution BuildResolution(CardPlay play)
	{
		if (play.IsAutoPlay)
		{
			return new FreePlayResolution(IsAutoPlayNoSpend: true, IsCardBindingFree: false, IsRegisteredDetectorFree: false);
		}
		bool isCardBindingFree = EvaluateCardBindings(play);
		bool isRegisteredDetectorFree = EvaluateRegisteredDetectors(play);
		return new FreePlayResolution(IsAutoPlayNoSpend: false, isCardBindingFree, isRegisteredDetectorFree);
	}

	private static bool EvaluateCardBindings(CardPlay play)
	{
		CardModel card = play.Card;
		CardFreeBindingState orCreate = CardStates.GetOrCreate(card);
		ICombatState val = ResolveCombatState(card);
		if (orCreate.BaseCostsFreeThisCombatState != null && orCreate.BaseCostsFreeThisCombatState == val)
		{
			return true;
		}
		if (orCreate.BaseCostsFreeThisTurnCharges > 0)
		{
			return true;
		}
		if (orCreate.BaseCostsFreeForRestOfTurnCharges > 0)
		{
			return true;
		}
		return orCreate.BaseCostsFreeNextPlayCharges > 0;
	}

	private static bool EvaluateRegisteredDetectors(CardPlay play)
	{
		KeyValuePair<string, Func<CardPlay, bool>>[] array;
		using (Gate.EnterScope())
		{
