		}
		KeyValuePair<string, Func<CardPlay, bool>>[] array2 = array;
		for (int i = 0; i < array2.Length; i++)
		{
			KeyValuePair<string, Func<CardPlay, bool>> keyValuePair = array2[i];
			var (value, func2) = (KeyValuePair<string, Func<CardPlay, bool>>)(ref keyValuePair);
			try
			{
				if (func2(play))
